import{_ as t,c as l,o as s,j as a,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易辨画卷四十","description":"周易辨画 - 周易辨画卷四十","frontmatter":{"title":"周易辨画卷四十","description":"周易辨画 - 周易辨画卷四十"},"headers":[],"relativePath":"zh/classics/bianhua/041.md","filePath":"zh/classics/bianhua/041.md"}'),r={name:"zh/classics/bianhua/041.md"};function i(c,e,o,p,d,u){return s(),l("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易辨画卷四十",tabindex:"-1"},[n("周易辨画卷四十 "),a("a",{class:"header-anchor",href:"#周易辨画卷四十","aria-label":"Permalink to “周易辨画卷四十”"},"​")],-1),a("p",null,"钦定四库全书",-1),a("p",null,"颍川连斗山撰",-1),a("p",null,"大衍之数五十，加五则为河图，减五则为洛书。此河洛二图，圣人所为则之而作易也。朱子易学启蒙曰：图之左方，阳内阴外，即先天之震、离、兑、乾，阳长而阴消也。其右方阴内阳外，即先天之巽、坎、艮、坤，阴长而阳消也。盖所以象二气之交运也。朱子易学启蒙曰：阳道主变，其数以进为极；阴道主化，其数以退为极。阳以进为极，故乾为父而得九，震长男而得八，坎中男而得七，艮少男而得六。凡成数皆阳主之。阴以退为极，故坤为母而得一，巽长女而得二，离中女而得三，兑少女而得四。凡生数皆阴主之，所以五数、十数不同。右伏羲八卦次序之图。系辞传曰：「易有太极，是生两仪，两仪生四象，四象生八卦。」邵子曰：「一分为二，二分为四，四分为八也。」朱子易学启蒙曰：图之一六为水，居北，即后天之坎位也；三八为木，居东，即后天震、巽之位也；三七为火，居南，即后天之离位也；四九为金，居西，即后天兑、乾之位也。五十为土，居中。即后天之坤、艮，周流四季，而偏旺于丑、未之交也。盖所以象五行之顺布也。朱子易学启蒙曰：「火上水下，故九数为离，一数为坎。火生燥土，故八次九为艮。燥土生金，故七、六次八而为兑，为乾。水生湿土，故二次一而为坤。湿土生木，故三、四次二而为震，为巽。以八数与八卦相配，而后天之位合矣。」右见说卦。邵子曰：「此文王八卦，乃入用之位，后天之学也。」又曰：「乾统三男于东北，坤统三女于西南。」按，四阳卦与四阴卦画各相配，阳数奇，三男皆五数，合父三数，共十八数。阴数偶，三女皆四数，合母六数，亦共十八数。䷀乾变六 一变 ䷫姤䷌ 同人 ䷉履䷈ 小畜 ䷍ 大有 ䷪夬 变五二变 ䷠遁䷅讼䷸巽䷱鼎䷛ 大过 ䷘ 无妄 ䷤ 家人 ䷝离䷰革䷼ 中孚 ䷥睽䷹",-1),a("p",null,"兑䷙ 大畜 ䷄需䷡ 大变壮四、三变 ䷋否䷴渐䷷旅䷞咸䷺涣䷿ 未济 ䷮困䷑蛊䷯井䷟恒䷩益䷔ 噬嗑 ䷐随䷕贲䷾ 既济 ䷶",-1),a("p",null,"丰䷨损䷻节䷵ 归妹 ䷊ 泰变 三、 四变 ䷓观䷢晋䷬萃䷳艮䷦蹇䷽ 小过 ䷃蒙䷜坎䷧解䷭",-1),a("p",null,"升䷚颐䷂屯䷲震䷣ 明夷 ䷒临 变二、",-1),a("p",null,"五变 ䷖剥䷇比䷏豫䷎谦䷆师䷗复 变一、 六变䷁坤此图即前图而横布之，乾、坤列上下之位，离、坎居乾、坤之间，盖离之中画即坤，坎之中画即乾也。乾、坤二画消长于诸卦之中，而一岁之气运一周焉。后天序卦反对原图乾䷀乾坤䷁坤屯䷂蒙需䷄讼师䷆比 小畜 ䷉履泰䷊否 同人 ䷌ 有大 谦䷎豫随䷐蛊临䷒观 噬嗑 ䷔贲剥䷖复 无妄 ䷘ 畜大 颐䷚頣 大过 ䷛ 过大 坎䷜坎离䷝离咸䷞恒遁䷠ 壮大 晋䷢ 夷家明人 ䷤暌蹇䷞解损䷨益夬䷪姤萃䷬升困䷮井革䷰鼎震䷲艮渐䷴ 妹归 丰䷶旅巽䷸兑涣䷺节 中孚 ䷼ 孚小中过 ䷽ 过既小济 ䷾ 济末 乾、坤、坎、离不易之卦，故上经以乾、坤居首，坎、离居终。乾交坤而为否，坤交乾而为泰，故上经十二卦而成居泰。兑、巽、震、艮反易之卦，故下经以兑艮、震巽相交居首，坎、离相交居终。艮交兑而为损，巽交震而为益，故下经十二卦而成损益。否、泰以天道言，损益以人事言也。右十二卦合十二支，而年月日时皆该周易办画。卷四十",-1)])])}const _=t(r,[["render",i]]);export{m as __pageData,_ as default};
